function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sb($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>45]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$h=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return ['ok'=>$h>=200&&$h<300,'body'=>$b];}
$msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $town=trim($_POST['town']??'Fairfield');$street=strtoupper(trim($_POST['street_name']??''));$notes=trim($_POST['project_notes']??''); if($street){$r=sb('POST','street_projects',[['town'=>$town,'street_name'=>$street,'project_status'=>'new','project_notes'=>$notes,'created_at'=>date('c'),'updated_at'=>date('c')]]);$msg=$r['ok']?'Street project created. Run Street Intelligence next.':'Error: '.$r['body'];}}
